"""
make_web_L9.py -- writes lectures/L9/web_en.md and web_ro.md (the text of the web lecture, format of
lectures/common/build_web_lecture.py), with every number read from L9_numbers.json and the frame hashes read from the
decks, then builds web/L9.html, web/L9_ro.html and web/L9_log.txt.
Run after build_L9.py:  python3 lectures/L9/make_web_L9.py
"""
import json
import os
import re
import subprocess
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
COMMON = os.path.join(HERE, "..", "common")
sys.path.insert(0, COMMON)
import build_web_lecture as bw  # noqa: E402

K = 9
N = json.load(open(os.path.join(HERE, f"L{K}_numbers.json")))


def get(key):
    v = N
    for p in key.split("."):
        v = v[p]
    return v


MON = {"en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
       "ro": ["ianuarie", "februarie", "martie", "aprilie", "mai", "iunie", "iulie", "august", "septembrie", "octombrie",
              "noiembrie", "decembrie"]}


def fmt(x, spec, lang):
    if isinstance(x, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", x):
        return f"{int(x[8:10])} {MON[lang][int(x[5:7]) - 1]} {x[:4]}"
    s = format(x, spec)
    if lang == "ro":
        s = s.replace(",", " ").replace(".", ",")
    if s.startswith("-"):
        s = "−" + s[1:]
    return s


class Page:
    def __init__(self, lang):
        self.lang = lang
        self.out = []
        self.deck = bw.read_deck(K, lang)

    def v(self, key, spec=""):
        return fmt(get(key), spec, self.lang)

    def h(self, title_start):
        """Hash of the first frame whose (plain) title starts with title_start."""
        key = re.sub(r"[^a-z0-9]", "", unicodedata.normalize("NFKD", title_start).lower())
        for f in self.deck["frames"]:
            t = re.sub(r"[^a-z0-9]", "", unicodedata.normalize("NFKD", f["title"]).lower())
            if t.startswith(key):
                return f["hash"]
        raise KeyError(f"no frame starting with: {title_start}")

    def add(self, s):
        self.out.append(s.strip("\n") + "\n")

    def block(self, title, frame=None, text=""):
        hh = f" {{h={self.h(frame or title)}}}" if (frame or title) else ""
        self.add(f"## {title}{hh}\n\n{text.strip()}\n")

    def write(self):
        with open(os.path.join(HERE, f"web_{self.lang}.md"), "w", encoding="utf-8") as fh:
            fh.write("\n".join(self.out))


def page(lang):
    P = Page(lang)
    v = P.v
    en = lang == "en"
    T = (lambda a, b: a if en else b)
    P.add(f"<!--\nWeb version of Lecture {K} ({lang.upper()}). Generated by lectures/L{K}/make_web_L{K}.py from L{K}_numbers.json and the deck;"
          f" built into web/L{K}{'' if en else '_ro'}.html by lectures/common/build_web_lecture.py.\n-->\n")
    P.add("## @intro\n")
    P.add(T(
        "Money laundering is rarely visible in a single payment. It shows in the chain: funds split across many addresses, passed through intermediaries and merged again. "
        "Banks, payment processors and crypto exchanges therefore look at transactions as a network, and graph neural networks (GNN) are the deep-learning tool built for that view: "
        "each transaction learns from its neighbours, its neighbours' neighbours, and so on.",
        "Spălarea banilor se vede rareori într-o singură plată. Se vede în lanț: fondurile sînt împărțite pe multe adrese, trecute prin intermediari și reunite apoi. "
        "De aceea băncile, procesatorii de plăți și platformele de schimb cripto privesc tranzacțiile ca pe o rețea, iar rețelele neuronale pe grafuri (GNN) sînt instrumentul de deep learning construit pentru această perspectivă: "
        "fiecare tranzacție învață de la vecinii ei, de la vecinii vecinilor și așa mai departe."))
    P.add(T(
        f"This lecture builds the three classic GNN layers, the graph convolutional network (GCN), graph sample and aggregate (GraphSAGE) and the graph attention network (GAT), and tests them for anti-money laundering (AML) "
        f"on the Elliptic graph of {v('data.n_nodes', ',')} Bitcoin transactions released by Weber et al. (2019), against a logistic regression and a random forest, in time order and with the measures that matter to an investigation team.",
        f"Cursul construiește cele trei straturi GNN clasice, rețeaua convoluțională pe graf (GCN), eșantionarea și agregarea pe graf (GraphSAGE) și rețeaua cu atenție pe graf (GAT), și le testează pentru combaterea spălării banilor (AML) "
        f"pe graful Elliptic cu {v('data.n_nodes', ',')} de tranzacții Bitcoin publicat de Weber et al. (2019), alături de o regresie logistică și o pădure aleatoare, în ordine cronologică și cu măsurile care contează pentru o echipă de investigații."))
    P.add("@goals")
    P.add(T(
        "- **Represent** financial data as a graph: nodes, edges, features, adjacency and normalised adjacency.\n"
        "- **Write** the message-passing scheme and the GCN, GraphSAGE and GAT layers with every symbol defined.\n"
        "- **Train** them on the Elliptic graph in time order, against strong non-graph benchmarks.\n"
        "- **Judge** the results with precision, recall, the area under the precision-recall curve (PR-AUC), alert budgets, drift and the stability of explanations.\n",
        "- **Reprezentați** datele financiare ca graf: noduri, muchii, variabile, matricea de adiacență și adiacența normalizată.\n"
        "- **Scrieți** schema de transmitere a mesajelor și straturile GCN, GraphSAGE și GAT, cu toate simbolurile definite.\n"
        "- **Antrenați-le** pe graful Elliptic, în ordine cronologică, alături de modele de referință puternice fără graf.\n"
        "- **Judecați** rezultatele cu precizia, recall-ul, aria de sub curba precizie-recall (PR-AUC), bugetele de alerte, schimbarea în timp și stabilitatea explicațiilor.\n"))

    # 1
    P.add(T("# Graphs in the detection of financial crime\n\nThe Elliptic graph shows what a transaction network looks like and why the neighbours carry information.",
            "# Grafurile în detectarea infracțiunilor financiare\n\nGraful Elliptic arată cum arată o rețea de tranzacții și de ce vecinii poartă informație."))
    P.block(T("Network structure in money-laundering detection", "Structura de rețea în detectarea spălării banilor"), text=T(
        f"""A graph $G=(\\mathcal V,\\mathcal E,\\mathbf X)$ has nodes $\\mathcal V$ (here transactions), edges $\\mathcal E$ (a payment flow from one transaction to the next) and a feature matrix $\\mathbf X\\in\\mathbb R^{{n\\times d}}$; the label $y_v=1$ marks an illicit transaction (scams, ransomware, dark markets). The Elliptic graph has {v('data.n_nodes', ',')} transactions, {v('data.n_edges', ',')} payment flows, {v('data.n_features')} features per transaction and {v('data.n_steps')} time steps. The task is node classification.

@practice a bank's anti-money-laundering team already thinks in chains of payments; a GNN learns from the same chains.""",
        f"""Un graf $G=(\\mathcal V,\\mathcal E,\\mathbf X)$ are nodurile $\\mathcal V$ (aici tranzacții), muchiile $\\mathcal E$ (un flux de plată de la o tranzacție la următoarea) și matricea variabilelor $\\mathbf X\\in\\mathbb R^{{n\\times d}}$; eticheta $y_v=1$ marchează o tranzacție ilicită (fraude, ransomware, piețe ilegale). Graful Elliptic are {v('data.n_nodes', ',')} de tranzacții, {v('data.n_edges', ',')} de fluxuri de plată, {v('data.n_features')} de variabile pe tranzacție și {v('data.n_steps')} de pași de timp. Sarcina este clasificarea nodurilor.

@practice echipa de conformitate a unei bănci gîndește deja în lanțuri de plăți; o rețea GNN învață din aceleași lanțuri."""))
    P.block(T("Description of the Elliptic data set", "Descrierea setului de date Elliptic"), text=T(
        f"""| Element | Value |
|---|---|
| Labels | {v('data.n_illicit', ',')} illicit, {v('data.n_licit', ',')} licit, {v('data.n_unknown', ',')} unknown ({v('data.pct_labelled', '.1f')} % labelled) |
| Features | {v('data.n_local')} local + {v('data.n_agg')} aggregated over the neighbours |
| Time | {v('data.n_steps')} steps of about two weeks; {v('data.pct_same_step', '.1f')} % of the edges join transactions of the same step |
| Training / test | steps 1–34 ({v('data.n_train', ',')} labelled) / steps 35–49 ({v('data.n_test', ',')} labelled, {v('data.n_test_illicit', ',')} illicit) |

Only {v('data.pct_illicit_lab', '.2f')} % of the labelled transactions are illicit, so accuracy alone would be meaningless. The feature names are anonymised by Elliptic.""",
        f"""| Element | Valoare |
|---|---|
| Etichete | {v('data.n_illicit', ',')} ilicite, {v('data.n_licit', ',')} licite, {v('data.n_unknown', ',')} necunoscute ({v('data.pct_labelled', '.1f')} % etichetate) |
| Variabile | {v('data.n_local')} locale și {v('data.n_agg')} agregate pe vecini |
| Timpul | {v('data.n_steps')} de pași de circa două săptămîni; {v('data.pct_same_step', '.1f')} % dintre muchii leagă tranzacții din același pas |
| Antrenare / test | pașii 1–34 ({v('data.n_train', ',')} etichetate) / pașii 35–49 ({v('data.n_test', ',')} etichetate, {v('data.n_test_illicit', ',')} ilicite) |

Doar {v('data.pct_illicit_lab', '.2f')} % dintre tranzacțiile etichetate sînt ilicite, deci acuratețea singură nu ar spune nimic. Denumirile variabilelor sînt anonimizate de Elliptic."""))
    P.block(T("Illicit transactions over time", "Evoluția în timp a tranzacțiilor ilicite"), text=T(
        f"""The number of illicit transactions peaks at {v('data.max_illicit_n')} in step {v('data.max_illicit_step')}; each step has about {v('data.nodes_per_step_mean', ',')} transactions in total. As in Weber et al. (2019), the models are trained on steps 1–34 and tested once on steps 35–49; the steps are never shuffled.

@chart elliptic_timesteps
Labelled transactions per time step, licit and illicit; the dashed line ends the training period.

@practice a model is judged on the months after its training data, exactly as it will be used.""",
        f"""Numărul tranzacțiilor ilicite atinge un vîrf de {v('data.max_illicit_n')} în pasul {v('data.max_illicit_step')}; fiecare pas are în total circa {v('data.nodes_per_step_mean', ',')} de tranzacții. Ca în Weber et al. (2019), modelele sînt antrenate pe pașii 1–34 și testate o singură dată pe pașii 35–49; pașii nu se amestecă niciodată.

@chart elliptic_timesteps
Tranzacțiile etichetate pe pași de timp, licite și ilicite; linia punctată încheie perioada de antrenare.

@practice un model este judecat pe lunile de după datele de antrenare, exact cum va fi folosit."""))
    P.block(T("Degree distribution of the transaction graph", "Distribuția gradelor în graful tranzacțiilor"), text=T(
        f"""The graph is sparse: the mean degree is {v('data.mean_degree', '.2f')}, the median {v('data.median_degree')}, and {v('data.pct_deg1', '.1f')} % of the nodes have a single neighbour. The tail is heavy: the largest hub has {v('data.max_degree')} neighbours. A GNN must not let such hubs drown everyone else, hence the degree normalisation of the next section.

@chart degree_dist
Complementary cumulative distribution of the degree, log-log scale.""",
        f"""Graful este rar: gradul mediu este {v('data.mean_degree', '.2f')}, mediana {v('data.median_degree')}, iar {v('data.pct_deg1', '.1f')} % dintre noduri au un singur vecin. Coada este grea: cel mai mare nod central are {v('data.max_degree')} de vecini. O rețea GNN nu trebuie să lase astfel de noduri să le acopere pe celelalte; de aici normalizarea după grad din secțiunea următoare.

@chart degree_dist
Funcția de repartiție complementară a gradului, pe scară dublu logaritmică."""))
    P.block(T("Homophily of illicit transactions", "Homofilia tranzacțiilor ilicite"), text=T(
        f"""Among the labelled neighbours of an illicit transaction, {v('homophily.illicit_nb_of_illicit_pct', '.1f')} % are illicit; for a licit transaction the share is {v('homophily.illicit_nb_of_licit_pct', '.1f')} %. Of the labelled edges, {v('homophily.edge_pct', '.1f')} % join two transactions of the same class, against {v('homophily.edge_random_pct', '.1f')} % if labels were assigned at random. This homophily is the reason to look at the neighbours.

@chart homophily
Share of illicit transactions among the labelled neighbours of illicit and of licit transactions.

@practice who you trade with says something about you: homophily is what a GNN exploits.""",
        f"""Dintre vecinii etichetați ai unei tranzacții ilicite, {v('homophily.illicit_nb_of_illicit_pct', '.1f')} % sînt ilicite; pentru o tranzacție licită ponderea este {v('homophily.illicit_nb_of_licit_pct', '.1f')} %. Dintre muchiile etichetate, {v('homophily.edge_pct', '.1f')} % leagă două tranzacții din aceeași clasă, față de {v('homophily.edge_random_pct', '.1f')} % dacă etichetele ar fi date la întîmplare. Această homofilie este motivul pentru care ne uităm la vecini.

@chart homophily
Ponderea tranzacțiilor ilicite printre vecinii etichetați ai tranzacțiilor ilicite și licite.

@practice cu cine tranzacționezi spune ceva despre tine: homofilia este ceea ce exploatează o rețea GNN."""))
    P.add("## @end\n\n" + T("Fraud graphs are sparse, heavy-tailed, labelled in waves and homophilous: neighbours carry information, but time must be respected.",
                             "Grafurile de fraudă sînt rare, cu cozi grele, etichetate în valuri și homofile: vecinii poartă informație, dar ordinea în timp trebuie respectată.") + "\n")

    # 2
    P.add(T("# Graphs as matrices\n\nAdjacency, degree and the Laplacian turn a graph into linear algebra.",
            "# Grafurile ca matrice\n\nMatricea de adiacență, matricea gradelor și laplacianul transformă graful în algebră liniară."))
    P.block(T("The adjacency matrix as an algebraic representation of the graph", "Matricea de adiacență ca reprezentare algebrică a grafului"), text=T(
        f"""$A_{{uv}}=1$ if $(u,v)$ is an edge and 0 otherwise; $D=\\operatorname{{diag}}(\\sum_vA_{{uv}})$ is the degree matrix. Adding self-loops and normalising symmetrically gives

$$ \\tilde A=A+I,\\qquad \\hat A=\\tilde D^{{-1/2}}\\tilde A\\,\\tilde D^{{-1/2}}, $$ {{#eq:ahat}}

whose entries are $1/\\sqrt{{\\tilde d_u\\tilde d_v}}$. The matrix $A$ has about $4\\cdot10^{{10}}$ cells but only {v('data.n_edges', ',')} edges, so libraries such as PyTorch Geometric (PyG) store an edge list. Without normalisation, a hub of degree {v('data.max_degree')} would add {v('data.max_degree')} messages and explode the scale.""",
        f"""$A_{{uv}}=1$ dacă $(u,v)$ este muchie și 0 altfel; $D=\\operatorname{{diag}}(\\sum_vA_{{uv}})$ este matricea gradelor. Adăugînd bucle și normalizînd simetric, obținem

$$ \\tilde A=A+I,\\qquad \\hat A=\\tilde D^{{-1/2}}\\tilde A\\,\\tilde D^{{-1/2}}, $$ {{#eq:ahat}}

cu elementele $1/\\sqrt{{\\tilde d_u\\tilde d_v}}$. Matricea $A$ are circa $4\\cdot10^{{10}}$ celule, dar numai {v('data.n_edges', ',')} de muchii, deci bibliotecile precum PyTorch Geometric (PyG) păstrează o listă de muchii. Fără normalizare, un nod central de grad {v('data.max_degree')} ar aduna {v('data.max_degree')} de mesaje, iar scala ar exploda."""))
    P.block(T("Permutation invariance and equivariance of graph models", "Invarianța și echivarianța la permutări ale modelelor pe graf"), text=T(
        """For every permutation matrix $P$, a node-level model must satisfy $f(P\\mathbf X,PAP^\\top)=Pf(\\mathbf X,A)$ (equivariance) and a graph-level model $g(P\\mathbf X,PAP^\\top)=g(\\mathbf X,A)$ (invariance). A multilayer perceptron (MLP) on the rows of $A$ would change with the numbering; a convolutional neural network (CNN) assumes a grid with a fixed number of ordered neighbours, while a transaction has between 1 and hundreds of neighbours in no order.

@practice ask of any vendor model: does the score change if the input file is sorted differently? It must not.""",
        """Pentru orice matrice de permutare $P$, un model la nivel de nod trebuie să satisfacă $f(P\\mathbf X,PAP^\\top)=Pf(\\mathbf X,A)$ (echivarianță), iar unul la nivel de graf $g(P\\mathbf X,PAP^\\top)=g(\\mathbf X,A)$ (invarianță). Un perceptron multistrat (MLP) pe rîndurile lui $A$ s-ar schimba odată cu numerotarea; o rețea neuronală convoluțională (CNN) presupune o grilă cu un număr fix de vecini ordonați, pe cînd o tranzacție are între unul și cîteva sute de vecini, fără ordine.

@practice întrebați despre orice model cumpărat: se schimbă scorul dacă fișierul de intrare este sortat altfel? Nu are voie."""))
    P.block(T("Smooth signals on a graph: the Laplacian", "Semnale netede pe graf: laplacianul"), text=T(
        """The Laplacian $L=D-A$ measures how much a node signal differs between neighbours: $\\mathbf x^\\top L\\mathbf x=\\sum_{(u,v)\\in\\mathcal E}(x_u-x_v)^2$. Its eigenvectors $U$ define a graph Fourier transform, $\\hat{\\mathbf x}=U^\\top\\mathbf x$, and a spectral filter is $U g_\\theta(\\Lambda)U^\\top\\mathbf x$. That is costly, but a first-order polynomial in $L$ leads directly to the normalised adjacency of @eq:ahat (derivation in Appendix A of the slides). On homophilous fraud graphs the signal is smooth, so averaging over neighbours removes noise, not information.""",
        """Laplacianul $L=D-A$ măsoară cît diferă un semnal de la un nod la vecinii lui: $\\mathbf x^\\top L\\mathbf x=\\sum_{(u,v)\\in\\mathcal E}(x_u-x_v)^2$. Vectorii lui proprii $U$ definesc o transformată Fourier pe graf, $\\hat{\\mathbf x}=U^\\top\\mathbf x$, iar un filtru spectral este $U g_\\theta(\\Lambda)U^\\top\\mathbf x$. Calculul este costisitor, dar un polinom de gradul întîi în $L$ duce direct la adiacența normalizată din @eq:ahat (derivarea, în Anexa A a slide-urilor). Pe grafurile de fraudă cu homofilie semnalul este neted, deci media pe vecini elimină zgomot, nu informație."""))
    P.block(T("Three prediction tasks: node, edge and graph level", "Trei sarcini de predicție: la nivel de nod, de muchie și de graf"), text=T(
        """The same layers serve three questions; only the read-out changes. Node: is this transaction illicit (this lecture)? Edge: is this payment a transfer through a mule account? Graph: is this cluster of accounts a laundering ring, is this interbank network fragile? A sum over node representations makes a graph-level output independent of the numbering.

@practice define the unit of decision first (a payment, a client, a ring), then the graph task.""",
        """Aceleași straturi răspund la trei întrebări; se schimbă doar ieșirea. Nod: este această tranzacție ilicită (acest curs)? Muchie: este această plată un transfer printr-un cont intermediar? Graf: este acest grup de conturi o rețea de spălare, este această rețea interbancară fragilă? O sumă pe reprezentările nodurilor face ca ieșirea la nivel de graf să nu depindă de numerotare.

@practice stabiliți întîi unitatea de decizie (o plată, un client, o rețea), apoi sarcina pe graf."""))
    P.add("## @end\n\n" + T("A GNN works with the normalised adjacency and must be permutation-equivariant; the Laplacian explains why neighbour averages are low-pass filters.",
                             "O rețea GNN lucrează cu adiacența normalizată și trebuie să fie echivariantă la permutări; laplacianul explică de ce mediile pe vecini sînt filtre trece-jos.") + "\n")

    # 3
    P.add(T("# Message passing\n\nEvery GNN layer collects messages from the neighbours, aggregates them and updates the node.",
            "# Transmiterea mesajelor\n\nFiecare strat GNN colectează mesajele vecinilor, le agregă și actualizează nodul."))
    P.block(T("A GNN layer: message, aggregation and update functions", "Un strat GNN: funcțiile de mesaj, de agregare și de actualizare"), text=T(
        """A message-passing neural network (MPNN) computes, for each node $v$ and layer $l$,

$$ \\mathbf m_v^{(l)}=\\bigoplus_{u\\in\\mathcal N(v)}\\phi^{(l)}\\big(\\mathbf h_u^{(l)},\\mathbf h_v^{(l)},\\mathbf e_{uv}\\big),\\qquad \\mathbf h_v^{(l+1)}=\\psi^{(l)}\\big(\\mathbf h_v^{(l)},\\mathbf m_v^{(l)}\\big), $$ {#eq:mpnn}

starting from $\\mathbf h_v^{(0)}=\\mathbf x_v$, where $\\mathcal N(v)$ are the neighbours, $\\phi$ the message function, $\\bigoplus$ a permutation-invariant aggregator (sum, mean, max), $\\psi$ the update and $\\mathbf e_{uv}$ optional edge features. The weights are shared by all nodes, so the model size does not grow with the graph.""",
        """O rețea neuronală cu transmitere de mesaje (MPNN) calculează, pentru fiecare nod $v$ și strat $l$,

$$ \\mathbf m_v^{(l)}=\\bigoplus_{u\\in\\mathcal N(v)}\\phi^{(l)}\\big(\\mathbf h_u^{(l)},\\mathbf h_v^{(l)},\\mathbf e_{uv}\\big),\\qquad \\mathbf h_v^{(l+1)}=\\psi^{(l)}\\big(\\mathbf h_v^{(l)},\\mathbf m_v^{(l)}\\big), $$ {#eq:mpnn}

pornind de la $\\mathbf h_v^{(0)}=\\mathbf x_v$, unde $\\mathcal N(v)$ sînt vecinii, $\\phi$ funcția mesajului, $\\bigoplus$ un agregator care nu depinde de ordine (sumă, medie, maxim), $\\psi$ actualizarea, iar $\\mathbf e_{uv}$ variabile opționale ale muchiilor. Ponderile sînt comune tuturor nodurilor, deci dimensiunea modelului nu crește odată cu graful."""))
    P.block(T("The aggregator and the expressive power of a GNN", "Agregatorul și puterea de discriminare a unei rețele GNN"), text=T(
        """Mean and max forget how many neighbours sent a message: the neighbourhoods $\\{a,a\\}$ and $\\{a\\}$ have the same mean and the same maximum, but different sums. The graph isomorphism network (GIN) uses $\\mathbf h_v^{(l+1)}=\\mathrm{MLP}\\big((1+\\varepsilon)\\mathbf h_v^{(l)}+\\sum_{u}\\mathbf h_u^{(l)}\\big)$ and is as discriminative as the Weisfeiler–Leman (WL) test. In fraud, ``one payment from a mixer'' and ``ten payments from mixers'' should not look the same; but sums over hubs need normalisation, which is why the GCN uses @eq:ahat.

@practice choose the aggregator for the question: counts matter (sum), proportions matter (mean), one red flag matters (max).""",
        """Media și maximul uită cîți vecini au trimis mesaje: vecinătățile $\\{a,a\\}$ și $\\{a\\}$ au aceeași medie și același maxim, dar sume diferite. Rețeaua de izomorfism pe graf (GIN) folosește $\\mathbf h_v^{(l+1)}=\\mathrm{MLP}\\big((1+\\varepsilon)\\mathbf h_v^{(l)}+\\sum_{u}\\mathbf h_u^{(l)}\\big)$ și deosebește la fel de bine ca testul Weisfeiler–Leman (WL). În fraudă, „o plată de la un serviciu de amestecare” și „zece astfel de plăți” nu trebuie să arate la fel; dar sumele pe nodurile centrale cer normalizare, de aceea GCN folosește @eq:ahat.

@practice alegeți agregatorul după întrebare: contează numărul (suma), contează proporția (media), contează un singur semnal de alarmă (maximul)."""))
    P.block(T("Each layer widens the neighbourhood that reaches a node", "Fiecare strat lărgește vecinătatea care ajunge la un nod"), text=T(
        f"""An $L$-layer network sees the $L$-hop neighbourhood. For 2,000 test transactions the median number of nodes that can influence a node is {v('receptive.k1_median')} after one layer, {v('receptive.k2_median')} after two and {v('receptive.k4_median')} after four; the 90th percentile reaches {v('receptive.k4_p90', ',')} nodes after four layers, because hubs connect distant parts of the graph.

@chart receptive_field
Number of nodes within $k$ hops of a test transaction, median and 90th percentile.""",
        f"""O rețea cu $L$ straturi vede vecinătatea de $L$ salturi. Pentru 2 000 de tranzacții de test, numărul median de noduri care pot influența un nod este {v('receptive.k1_median')} după un strat, {v('receptive.k2_median')} după două și {v('receptive.k4_median')} după patru; percentila 90 ajunge la {v('receptive.k4_p90', ',')} de noduri după patru straturi, pentru că nodurile centrale leagă părți îndepărtate ale grafului.

@chart receptive_field
Numărul de noduri aflate la cel mult $k$ salturi de o tranzacție de test, mediana și percentila 90."""))
    P.block(T("Over-smoothing in deep graph networks", "Netezirea excesivă (over-smoothing) în rețelele pe graf cu multe straturi"), text=T(
        f"""Repeated degree-weighted averaging drives all representations towards a common vector. On Elliptic the test PR-AUC is {v('depth.ap_1', '.3f')} with one GCN layer, {v('depth.ap_2', '.3f')} with two and {v('depth.ap_6', '.3f')} with six; the best depth is {v('depth.best_layers')}. Over the same range the mean cosine similarity of node representations rises from {v('depth.cos_1', '.2f')} to {v('depth.cos_6', '.2f')}.

@chart oversmoothing
Test PR-AUC and mean cosine similarity of the node representations by number of GCN layers (mean of 2 seeds).

@practice GNNs are shallow by design: two or three layers, then residual links if more is needed.""",
        f"""Medierea repetată, ponderată după grad, aduce toate reprezentările spre un vector comun. Pe Elliptic, PR-AUC de test este {v('depth.ap_1', '.3f')} cu un strat GCN, {v('depth.ap_2', '.3f')} cu două și {v('depth.ap_6', '.3f')} cu șase; adîncimea cea mai bună este {v('depth.best_layers')}. Pe același interval, similaritatea cosinus medie a reprezentărilor crește de la {v('depth.cos_1', '.2f')} la {v('depth.cos_6', '.2f')}.

@chart oversmoothing
PR-AUC de test și similaritatea cosinus medie a reprezentărilor, după numărul de straturi GCN (media pe 2 semințe).

@practice rețelele GNN sînt intenționat puțin adînci: două-trei straturi, apoi conexiuni reziduale dacă este nevoie de mai mult."""))
    P.add("## @end\n\n" + T("Message passing = message, aggregation, update; depth = hops, and too much depth over-smooths.",
                             "Transmiterea mesajelor = mesaj, agregare, actualizare; adîncimea = numărul de salturi, iar prea multă adîncime netezește excesiv.") + "\n")

    # 4
    P.add(T("# GCN, GraphSAGE and GAT\n\nThree choices of message, aggregation and update, from fixed degree weights to learned attention.",
            "# GCN, GraphSAGE și GAT\n\nTrei alegeri ale mesajului, agregării și actualizării, de la ponderi fixe după grad la atenție învățată."))
    P.block(T("GCN: degree-weighted average of the neighbours followed by a linear map", "GCN: media vecinilor ponderată cu gradele, urmată de o transformare liniară"), text=T(
        f"""A GCN layer is

$$ H^{{(l+1)}}=\\mathrm{{ReLU}}\\big(\\hat AH^{{(l)}}W^{{(l)}}\\big), $$ {{#eq:gcn}}

a linear regression on the normalised average of a node and its neighbours, followed by the rectified linear unit (ReLU). Our GCN has 2 layers of 100 hidden units and dropout 0.2, {v('gcn_params', ',')} parameters, and is trained on the whole graph at once in about {v('models.gcn.sec', '.0f')} seconds per seed on a laptop processor. The cost per layer is linear in the number of edges.

@practice a GCN is the graph analogue of a moving average: robust, cheap, and blind to which neighbour matters most.""",
        f"""Un strat GCN este

$$ H^{{(l+1)}}=\\mathrm{{ReLU}}\\big(\\hat AH^{{(l)}}W^{{(l)}}\\big), $$ {{#eq:gcn}}

o regresie liniară pe media normalizată a nodului și a vecinilor lui, urmată de unitatea liniară rectificată (ReLU). Rețeaua noastră GCN are 2 straturi cu 100 de unități ascunse și dropout 0,2, {v('gcn_params', ',')} de parametri, și se antrenează pe tot graful deodată în circa {v('models.gcn.sec', '.0f')} de secunde pe sămînță, pe procesorul unui laptop. Costul pe strat este liniar în numărul de muchii.

@practice o rețea GCN este analogul pe graf al unei medii mobile: robustă, ieftină și oarbă la care vecin contează cel mai mult."""))
    P.block(T("GraphSAGE: separate node representation and neighbour sampling", "GraphSAGE: reprezentarea separată a nodului și eșantionarea vecinilor"), text=T(
        f"""GraphSAGE uses separate weights for the node and for the mean of a sample $\\mathcal S(v)$ of its neighbours: $\\mathbf h_v^{{(l+1)}}=\\mathrm{{ReLU}}\\big(W_1\\mathbf h_v^{{(l)}}+W_2\\,\\mathrm{{mean}}_{{u\\in\\mathcal S(v)}}\\mathbf h_u^{{(l)}}\\big)$. The weights do not depend on the graph, so tomorrow's transactions get a score without retraining (inductive learning), and sampling bounds the cost per node. On Elliptic its illicit-class F1 is {v('models.sage.f1', '.3f')} (standard deviation {v('models.sage.f1_sd', '.3f')}) and its PR-AUC {v('models.sage.ap', '.3f')}.""",
        f"""GraphSAGE folosește ponderi separate pentru nod și pentru media unui eșantion $\\mathcal S(v)$ de vecini: $\\mathbf h_v^{{(l+1)}}=\\mathrm{{ReLU}}\\big(W_1\\mathbf h_v^{{(l)}}+W_2\\,\\mathrm{{mean}}_{{u\\in\\mathcal S(v)}}\\mathbf h_u^{{(l)}}\\big)$. Ponderile nu depind de graf, deci tranzacțiile de mîine primesc un scor fără reantrenare (învățare inductivă), iar eșantionarea limitează costul pe nod. Pe Elliptic, F1 pe clasa ilicită este {v('models.sage.f1', '.3f')} (abatere standard {v('models.sage.f1_sd', '.3f')}), iar PR-AUC {v('models.sage.ap', '.3f')}."""))
    P.block(T("GAT: learned attention weights over the neighbours", "GAT: ponderi de atenție învățate pentru vecini"), text=T(
        f"""A graph attention layer weights each neighbour by a learned score,

$$ \\alpha_{{vu}}=\\operatorname{{softmax}}_u\\Big(\\mathrm{{LeakyReLU}}\\big(\\mathbf a^\\top[W\\mathbf h_v\\,\\|\\,W\\mathbf h_u]\\big)\\Big), $$ {{#eq:gat}}

and averages $W\\mathbf h_u$ with these weights, with several heads concatenated. It is the attention of Lecture 7 restricted to the edges of the graph: a transformer is a GAT on the complete graph of the tokens. Our GAT has 4 heads, {v('gat_params', ',')} parameters, an illicit F1 of {v('models.gat.f1', '.3f')} and a PR-AUC of {v('models.gat.ap', '.3f')}.

@practice attention weights are a first, not a final, explanation: they show where the model looked, not why.""",
        f"""Un strat cu atenție pe graf ponderează fiecare vecin cu un scor învățat,

$$ \\alpha_{{vu}}=\\operatorname{{softmax}}_u\\Big(\\mathrm{{LeakyReLU}}\\big(\\mathbf a^\\top[W\\mathbf h_v\\,\\|\\,W\\mathbf h_u]\\big)\\Big), $$ {{#eq:gat}}

și face media lui $W\\mathbf h_u$ cu aceste ponderi, cu mai multe capete concatenate. Este atenția din cursul 7, restrînsă la muchiile grafului: un transformer este o rețea GAT pe graful complet al tokenilor. Rețeaua noastră GAT are 4 capete, {v('gat_params', ',')} de parametri, F1 pe clasa ilicită {v('models.gat.f1', '.3f')} și PR-AUC {v('models.gat.ap', '.3f')}.

@practice ponderile de atenție sînt o primă explicație, nu una finală: arată unde s-a uitat modelul, nu de ce."""))
    P.block(T("Training on one big graph: masks, class weights, early stopping", "Antrenarea pe un singur graf mare: măști, ponderi de clasă, oprire timpurie"), text=T(
        f"""All nodes pass messages, but only the labelled nodes of steps 1–29 enter the weighted cross-entropy, with weights 0.7 for illicit and 0.3 for licit as in Weber et al. (2019). The labelled nodes of steps 30–34 choose the best epoch by PR-AUC (patience 40); the median epoch kept by the GCN is {v('models.gcn.best_epoch_median')}. Feature means and standard deviations come from steps 1–34 only. The unknown nodes are not wasted: they carry messages between labelled ones (semi-supervised learning).""",
        f"""Toate nodurile transmit mesaje, dar în entropia încrucișată ponderată intră numai nodurile etichetate din pașii 1–29, cu ponderile 0,7 pentru ilicite și 0,3 pentru licite, ca în Weber et al. (2019). Nodurile etichetate din pașii 30–34 aleg epoca cea mai bună după PR-AUC (răbdare 40 de epoci); epoca mediană reținută de GCN este {v('models.gcn.best_epoch_median')}. Mediile și abaterile standard ale variabilelor provin numai din pașii 1–34. Nodurile necunoscute nu se pierd: ele transmit mesaje între cele etichetate (învățare semi-supervizată)."""))
    P.add("## @end\n\n" + T("GCN averages with degree weights, GraphSAGE separates self and neighbours and is inductive, GAT learns the weights.",
                             "GCN face media cu ponderi după grad, GraphSAGE separă nodul de vecini și este inductivă, GAT învață ponderile.") + "\n")

    # 5
    P.add(T("# Case study: illicit Bitcoin transactions\n\nEight models on the same temporal test, judged like an investigation team would judge them.",
            "# Studiu de caz: tranzacții Bitcoin ilicite\n\nOpt modele pe același test în timp, judecate cum le-ar judeca o echipă de investigații."))
    P.block(T("Eight models evaluated on a chronological test set", "Opt modele evaluate pe un set de test cronologic"), text=T(
        f"""The models are a logistic regression on the {v('data.n_local')} local features and on all {v('data.n_features')} features; a random forest with 100 trees and 50 features per split, as in Weber et al. (2019); an MLP with the same layers as the GCN but no messages, which isolates the value of the edges; GCN, GraphSAGE and GAT; and a random forest on the features plus the 100 hidden GCN outputs. Precision, recall and F1 of the illicit class are measured at threshold 0.5 on steps 35–49, together with the threshold-free PR-AUC; each network and forest is run with {v('models.gcn.n_runs')} seeds.""",
        f"""Modelele sînt: o regresie logistică pe cele {v('data.n_local')} de variabile locale și pe toate cele {v('data.n_features')}; o pădure aleatoare cu 100 de arbori și 50 de variabile la fiecare împărțire, ca în Weber et al. (2019); un MLP cu aceleași straturi ca GCN, dar fără mesaje, care izolează valoarea muchiilor; GCN, GraphSAGE și GAT; și o pădure aleatoare pe variabile plus cele 100 de ieșiri ascunse ale GCN. Precizia, recall-ul și F1 pe clasa ilicită se măsoară la pragul 0,5 pe pașii 35–49, împreună cu PR-AUC, care nu depinde de prag; fiecare rețea și pădure este rulată cu {v('models.gcn.n_runs')} semințe."""))
    P.block(T("Results on Elliptic: the random forest and the contribution of graph layers", "Rezultatele pe Elliptic: pădurea aleatoare și contribuția straturilor pe graf"), text=T(
        f"""The illicit-class F1 is {v('models.rf.f1', '.3f')} for the random forest, {v('models.rf_emb.f1', '.3f')} for the forest with GCN embeddings, {v('models.gcn.f1', '.3f')} for the GCN, {v('models.mlp.f1', '.3f')} for the MLP and {v('models.lr_all.f1', '.3f')} for the logistic regression. With the same layers, the edges change the PR-AUC of the network by {v('gcn_vs_mlp_ap_pts', '+.1f')} points (GCN against MLP), while its F1 at the 0.5 threshold is lower than the MLP's; GraphSAGE, which keeps the node apart from its neighbours, is the best graph network, with F1 {v('models.sage.f1', '.3f')}.

@chart model_comparison
Illicit-class F1 and PR-AUC on test steps 35–49, mean and standard deviation over the seeds.""",
        f"""F1 pe clasa ilicită este {v('models.rf.f1', '.3f')} pentru pădurea aleatoare, {v('models.rf_emb.f1', '.3f')} pentru pădurea cu reprezentări GCN, {v('models.gcn.f1', '.3f')} pentru GCN, {v('models.mlp.f1', '.3f')} pentru MLP și {v('models.lr_all.f1', '.3f')} pentru regresia logistică. Cu aceleași straturi, muchiile schimbă PR-AUC al rețelei cu {v('gcn_vs_mlp_ap_pts', '+.1f')} puncte (GCN față de MLP), deși F1 la pragul 0,5 este mai mic decît al MLP; GraphSAGE, care separă nodul de vecini, este cea mai bună rețea pe graf, cu F1 {v('models.sage.f1', '.3f')}.

@chart model_comparison
F1 pe clasa ilicită și PR-AUC pe pașii de test 35–49, media și abaterea standard pe semințe."""))
    P.block(T("Precision, recall and the cost of training", "Precizie, recall și costul antrenării"), text=T(
        f"""Precision is the share of alerts that are illicit; recall is the share of illicit transactions found. The random forest has precision {v('models.rf.prec', '.3f')} and recall {v('models.rf.rec', '.3f')}; the GCN has precision {v('models.gcn.prec', '.3f')} and recall {v('models.gcn.rec', '.3f')}; the logistic regression, with class weights 0.3 and 0.7, buys a recall of {v('models.lr_all.rec', '.3f')} with a precision of only {v('models.lr_all.prec', '.3f')}.

@practice the right model depends on what an error costs: a missed laundering case or an analyst's wasted hour.""",
        f"""Precizia este ponderea alertelor care sînt ilicite; recall-ul este ponderea tranzacțiilor ilicite găsite. Pădurea aleatoare are precizia {v('models.rf.prec', '.3f')} și recall-ul {v('models.rf.rec', '.3f')}; GCN are precizia {v('models.gcn.prec', '.3f')} și recall-ul {v('models.gcn.rec', '.3f')}; regresia logistică, cu ponderile de clasă 0,3 și 0,7, cumpără un recall de {v('models.lr_all.rec', '.3f')} cu o precizie de doar {v('models.lr_all.prec', '.3f')}.

@practice modelul potrivit depinde de costul unei erori: un caz de spălare ratat sau o oră pierdută de un analist."""))
    P.block(T("Precision-recall curves of the models", "Curbele precizie-recall ale modelelor"), text=T(
        f"""The PR-AUC is {v('models.rf.ap', '.3f')} for the random forest, {v('models.rf_emb.ap', '.3f')} for the forest with GCN embeddings, {v('models.gcn.ap', '.3f')} for the GCN and {v('models.lr_all.ap', '.3f')} for the logistic regression; a random score would give {v('data.pct_test_illicit', '.2f')} %, the share of illicit among the labelled test transactions.

@chart pr_curves
Precision-recall curves on the test steps (scores averaged over the seeds); the dotted line is the base rate.""",
        f"""PR-AUC este {v('models.rf.ap', '.3f')} pentru pădurea aleatoare, {v('models.rf_emb.ap', '.3f')} pentru pădurea cu reprezentări GCN, {v('models.gcn.ap', '.3f')} pentru GCN și {v('models.lr_all.ap', '.3f')} pentru regresia logistică; un scor aleator ar da {v('data.pct_test_illicit', '.2f')} %, ponderea tranzacțiilor ilicite printre cele etichetate de test.

@chart pr_curves
Curbele precizie-recall pe pașii de test (scoruri mediate pe semințe); linia punctată este rata de bază."""))
    P.block(T("Bootstrap test of the gap on the test transactions", "Testul bootstrap al diferenței pe tranzacțiile de test"), text=T(
        f"""Resampling the test transactions 1,000 times, with the same draw for both models, gives a PR-AUC difference of {v('boot.rf_minus_gcn_ap', '.3f')} between the random forest and the GCN, with a 95 % interval of [{v('boot.lo', '.3f')}; {v('boot.hi', '.3f')}], and a difference of {v('boot.rfemb_minus_rf_ap', '.3f')} between the forest with GCN embeddings and the plain forest, interval [{v('boot.lo2', '.3f')}; {v('boot.hi2', '.3f')}]. An interval that excludes zero supports a real difference on this test period.

@practice report the interval, not only the winner: a fraud committee decides on ranges, not on the third decimal.""",
        f"""Reeșantionînd tranzacțiile de test de 1 000 de ori, cu aceeași extragere pentru ambele modele, diferența de PR-AUC dintre pădurea aleatoare și GCN este {v('boot.rf_minus_gcn_ap', '.3f')}, cu intervalul de 95 % [{v('boot.lo', '.3f')}; {v('boot.hi', '.3f')}], iar diferența dintre pădurea cu reprezentări GCN și pădurea simplă este {v('boot.rfemb_minus_rf_ap', '.3f')}, cu intervalul [{v('boot.lo2', '.3f')}; {v('boot.hi2', '.3f')}]. Un interval care nu conține zero susține o diferență reală pe această perioadă de test.

@practice raportați intervalul, nu doar cîștigătorul: un comitet antifraudă decide pe intervale, nu pe a treia zecimală."""))
    P.block(T("Neighbourhood aggregates in the features and the performance of the random forest", "Agregatele de vecinătate din variabile și performanța pădurii aleatoare"), text=T(
        f"""{v('data.n_agg')} of the {v('data.n_features')} features are aggregates over the one-hop neighbours (maxima, minima, standard deviations, correlations): one fixed GNN layer computed by Elliptic before release. A logistic regression on the local features alone reaches an F1 of {v('models.lr_local.f1', '.3f')}, against {v('models.lr_all.f1', '.3f')} with the aggregates. Trees also fit rule-like fraud patterns well. GNNs earn their keep on raw graphs without engineered aggregates, on multi-hop patterns and in inductive scoring; combining both, the forest with GCN representations changes the F1 by {v('rfemb_vs_rf_f1_pts', '+.1f')} points.

@practice before training a GNN, check whether the data provider has already aggregated the neighbourhood for you.""",
        f"""{v('data.n_agg')} dintre cele {v('data.n_features')} de variabile sînt agregate pe vecinii de la un salt (maxime, minime, abateri standard, corelații): un strat GNN fix, calculat de Elliptic înainte de publicarea datelor. O regresie logistică numai pe variabilele locale atinge F1 {v('models.lr_local.f1', '.3f')}, față de {v('models.lr_all.f1', '.3f')} cu agregatele. În plus, arborii prind bine tiparele de fraudă de tip regulă. Rețelele GNN își justifică costul pe grafuri brute, fără agregate construite manual, pe tipare pe mai multe salturi și la scorurile inductive; combinînd cele două, pădurea cu reprezentări GCN schimbă F1 cu {v('rfemb_vs_rf_f1_pts', '+.1f')} puncte.

@practice înainte de a antrena o rețea GNN, verificați dacă furnizorul datelor nu a agregat deja vecinătatea."""))
    P.block(T("Concept drift after a dark-market shutdown", "Schimbarea conceptului după închiderea unei piețe ilegale"), text=T(
        f"""Before step 43 the mean F1 is {v('shutdown.rf_f1_pre', '.3f')} for the random forest and {v('shutdown.gcn_f1_pre', '.3f')} for the GCN; from step 43 it is {v('shutdown.rf_f1_post', '.3f')} and {v('shutdown.gcn_f1_post', '.3f')}. After a major dark market closed, illicit flows changed form (Weber et al., 2019), and no model trained on steps 1–34 had seen the new behaviour.

@chart f1_by_timestep
Illicit-class F1 per test time step for four models.

@practice monitor F1 per period and retrain on recent labels; a static AML model ages within weeks.""",
        f"""Înainte de pasul 43, F1 mediu este {v('shutdown.rf_f1_pre', '.3f')} pentru pădurea aleatoare și {v('shutdown.gcn_f1_pre', '.3f')} pentru GCN; de la pasul 43 este {v('shutdown.rf_f1_post', '.3f')} și {v('shutdown.gcn_f1_post', '.3f')}. După închiderea unei piețe ilegale importante, fluxurile ilicite și-au schimbat forma (Weber et al., 2019), iar niciun model antrenat pe pașii 1–34 nu văzuse noul comportament.

@chart f1_by_timestep
F1 pe clasa ilicită pe fiecare pas de timp de test, pentru patru modele.

@practice monitorizați F1 pe fiecare perioadă și reantrenați pe etichete recente; un model AML static îmbătrînește în cîteva săptămîni."""))
    P.block(T("Illicit transactions found among the top 1,000 alerts", "Tranzacțiile ilicite identificate între primele 1 000 de alerte"), frame=T("Illicit transactions found among", "Tranzacțiile ilicite identificate între"), text=T(
        f"""If the team reviews the {v('alerts.k', ',')} highest scores of the test period, it finds {v('alerts.rf', '.1f')} % of all illicit transactions with the random forest, {v('alerts.gcn', '.1f')} % with the GCN and {v('alerts.rf_emb', '.1f')} % with the forest plus GCN representations; the hit rate of those alerts is {v('alerts.rf_prec', '.1f')} % for the forest and {v('alerts.gcn_prec', '.1f')} % for the GCN, out of {v('alerts.n_test_illicit', ',')} illicit test transactions.

@chart alert_budget
Share of the illicit test transactions found among the highest scores, by number of alerts reviewed.

@practice size the team from this curve: the alert budget, not the F1, is the constraint in a compliance department.""",
        f"""Dacă echipa verifică primele {v('alerts.k', ',')} de scoruri din perioada de test, găsește {v('alerts.rf', '.1f')} % dintre toate tranzacțiile ilicite cu pădurea aleatoare, {v('alerts.gcn', '.1f')} % cu GCN și {v('alerts.rf_emb', '.1f')} % cu pădurea plus reprezentările GCN; rata de reușită a acestor alerte este {v('alerts.rf_prec', '.1f')} % pentru pădure și {v('alerts.gcn_prec', '.1f')} % pentru GCN, din {v('alerts.n_test_illicit', ',')} de tranzacții ilicite de test.

@chart alert_budget
Ponderea tranzacțiilor ilicite de test găsite printre scorurile cele mai mari, după numărul de alerte verificate.

@practice dimensionați echipa după această curbă: bugetul de alerte, nu F1, este constrîngerea unui departament de conformitate."""))
    P.block(T("Illicit transactions cluster in the GCN embedding space", "Tranzacțiile ilicite se grupează în spațiul de reprezentare al GCN"), text=T(
        f"""Projecting the {v('emb.dim')}-dimensional hidden layer of the GCN on its first two principal components (principal component analysis, PCA), which explain {v('emb.var2_pct', '.1f')} % of the variance, shows the illicit test transactions gathering in a region of their own. These vectors are the inputs of the forest-plus-GCN model and can feed any other risk model.

@chart gcn_embeddings
Hidden GCN representations of test transactions, first two principal components.""",
        f"""Proiecția stratului ascuns al rețelei GCN, cu {v('emb.dim')} de dimensiuni, pe primele două componente principale (analiza componentelor principale, PCA), care explică {v('emb.var2_pct', '.1f')} % din varianță, arată tranzacțiile ilicite de test adunîndu-se într-o regiune proprie. Acești vectori sînt intrările modelului pădure plus GCN și pot alimenta orice alt model de risc.

@chart gcn_embeddings
Reprezentările ascunse GCN ale tranzacțiilor de test, primele două componente principale."""))
    P.block(T("Effect of graph features on the explanations", "Efectul variabilelor de graf asupra explicațiilor"), text=T(
        f"""The 10 most important features of the random forest carry {v('stability.top10_share_rf_pct', '.1f')} % of its impurity importance; once the GCN representations are added, the same features keep {v('stability.top10_share_rfemb_pct', '.1f')} % and the representations take {v('stability.emb_share_pct', '.1f')} %. Across {v('stability.n_refits')} refits, the mean Spearman correlation of the importances is {v('stability.rf', '.3f')} for the forest and {v('stability.rf_emb', '.3f')} for the forest with GCN representations. Part of the change comes from adding inputs at all, and part from retraining: both must be accounted for before reading a change of model as a change of explanation.

@chart importance_shift
Importance of the 10 most important features of the random forest, without and with GCN representations.""",
        f"""Primele 10 variabile ale pădurii aleatoare au {v('stability.top10_share_rf_pct', '.1f')} % din importanța bazată pe impuritate; după adăugarea reprezentărilor GCN, aceleași variabile păstrează {v('stability.top10_share_rfemb_pct', '.1f')} %, iar reprezentările iau {v('stability.emb_share_pct', '.1f')} %. Pe {v('stability.n_refits')} reantrenări, corelația Spearman medie a importanțelor este {v('stability.rf', '.3f')} pentru pădure și {v('stability.rf_emb', '.3f')} pentru pădurea cu reprezentări GCN. O parte din schimbare vine din simpla adăugare de intrări, iar o parte din reantrenare: ambele trebuie luate în calcul înainte de a interpreta o schimbare de model ca o schimbare de explicație.

@chart importance_shift
Importanța primelor 10 variabile ale pădurii aleatoare, fără și cu reprezentări GCN."""))
    P.add("## @end\n\n" + T("On Elliptic the edges help a network, but a forest on pre-aggregated features leads; drift and alert budgets matter more than the third decimal.",
                             "Pe Elliptic muchiile ajută o rețea, dar o pădure pe variabile deja agregate conduce; schimbarea în timp și bugetul de alerte contează mai mult decît a treia zecimală.") + "\n")

    # 6
    P.add(T("# GNNs in production\n\nGraph models in finance fail in specific ways; knowing them is part of the model.",
            "# Rețelele GNN în producție\n\nModelele pe graf din finanțe greșesc în moduri specifice; cunoașterea lor face parte din model."))
    P.block(T("Common errors in applying graph models in finance", "Erori frecvente în aplicarea modelelor pe graf în finanțe"), text=T(
        f"""Leakage through edges: a test node must not receive messages from the future; in Elliptic {v('data.pct_same_step', '.1f')} % of the edges stay inside one time step, so the temporal split is clean. Few labels: only {v('data.pct_labelled', '.1f')} % of the nodes are labelled, and labels from past investigations favour the cases already found. Drift: criminals adapt, and temporal GNNs such as EvolveGCN let the weights evolve with time. Explainability: a suspicious-activity report needs a reason a regulator can read; GNNExplainer finds the subgraph and features behind one prediction.

@practice test a graph model the way it will run: on later periods, with the labels available at that time.""",
        f"""Scurgeri de informație prin muchii: un nod de test nu trebuie să primească mesaje din viitor; în Elliptic, {v('data.pct_same_step', '.1f')} % dintre muchii rămîn în același pas de timp, deci împărțirea în timp este curată. Puține etichete: doar {v('data.pct_labelled', '.1f')} % dintre noduri sînt etichetate, iar etichetele din investigațiile trecute favorizează cazurile deja găsite. Schimbarea în timp: infractorii se adaptează, iar rețelele GNN temporale precum EvolveGCN lasă ponderile să evolueze. Explicabilitatea: un raport de activitate suspectă are nevoie de o justificare pe care un supraveghetor o poate citi; GNNExplainer găsește subgraful și variabilele din spatele unei predicții.

@practice testați un model pe graf așa cum va funcționa: pe perioade ulterioare, cu etichetele disponibile atunci."""))
    P.block(T("Applications of graph models in finance", "Aplicații ale modelelor bazate pe grafuri în finanțe"), text=T(
        """Cardholder–merchant graphs link many fraud victims to one compromised terminal; guarantor and supplier networks carry defaults along trade credit; address and transaction graphs reveal mixers and wallet clusters; interbank exposures and tail-dependence networks show who falls if one bank fails; stocks linked by correlation, supply chain or ownership feed return forecasts; power grids and interconnected price zones are graphs by construction.

@practice whenever the risk of one unit depends on its counterparties, a graph model is worth a try.""",
        """Grafurile deținător–comerciant leagă multe victime de un singur terminal compromis; rețelele de garanți și furnizori propagă neplata prin creditul comercial; grafurile de adrese și tranzacții scot la iveală serviciile de amestecare și grupurile de portofele; expunerile interbancare și rețelele de dependență în cozi arată cine cade dacă o bancă cade; acțiunile legate prin corelație, lanț de aprovizionare sau acționariat alimentează prognozele randamentelor; rețelele electrice și zonele de preț interconectate sînt grafuri prin construcție.

@practice ori de cîte ori riscul unei unități depinde de contrapărțile ei, un model pe graf merită încercat."""))
    P.add("## @end\n\n" + T("Respect time, expect few and biased labels, monitor drift and explain decisions: these decide whether a graph model survives in production.",
                             "Respectați timpul, așteptați-vă la puține etichete și la etichete părtinitoare, urmăriți schimbarea în timp și explicați deciziile: de acestea depinde dacă un model pe graf rezistă în producție.") + "\n")
